```perl
## name = config-threshold-check
## descr = reads a threshold from config and warns on exceedance

## load the config module [ it defines %config ]
perlmod.load qw| perlmod.config |;

## read threshold from config [ default to 30 if absent ]
my $threshold = $config{'threshold'} // 30;

## check the provided value against the threshold
my $value = shift // 0;

if ( $value > $threshold ) {
    <[base.logs]>->(
        1,
        'value %d exceeds configured threshold %d',
        $value,
        $threshold,
    );
}

return { 'mode' => qw| true |, 'data' => $value };
```
